import{_ as r,a as o,b as a,c as d}from"./chunks/compare-toolbar.C0Xi3fiu.js";import{_ as e,o as i,c as s,a2 as n}from"./chunks/framework.Dx-TCpNt.js";const _=JSON.parse('{"title":"对照阅读","description":"对照阅读把两种或更多语言中的同一个分格并排放在一起——或叠放在一起——并让你把画面对齐，让对照真正可信。","frontmatter":{"description":"对照阅读把两种或更多语言中的同一个分格并排放在一起——或叠放在一起——并让你把画面对齐，让对照真正可信。"},"headers":[],"relativePath":"zh/guide/compare.md","filePath":"zh/guide/compare.md","lastUpdated":1794778665000}'),l={name:"zh/guide/compare.md"};function g(c,t,h,u,p,b){return i(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="对照阅读" tabindex="-1">对照阅读 <a class="header-anchor" href="#对照阅读" aria-label="Permalink to &quot;对照阅读&quot;">​</a></h1><p>对照阅读把两种或更多语言中的同一个分格并排放在一起——或叠放在一起——并让你把画面对齐，让对照真正可信。</p><figure class="shot"><img src="'+r+'" alt="对照阅读：同一页面的日语、中文和英语并排显示"><figcaption>三语并排模式。每种语言各占一栏；对齐按页面保存，并会应用在导出中。</figcaption></figure><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>同一本书的两个版本，画面很少能严丝合缝：生肉和熟肉之间总有偏移、裁切或缩放差异。整页对看会掩盖细微差别。<strong>逐格对照</strong>，并让每种语言独立对齐，才能看清措辞、语气和省略。</p><h2 id="布局" tabindex="-1">布局 <a class="header-anchor" href="#布局" aria-label="Permalink to &quot;布局&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控件</th><th>行为</th></tr></thead><tbody><tr><td><strong>语言标签</strong>（<code>JA</code>、<code>ZH</code>、<code>EN</code>……）</td><td>开启或关闭某种语言。本页缺失的语言会被禁用并显示提示。</td></tr><tr><td>拖动标签</td><td>调整各栏顺序。顺序会被记住。</td></tr><tr><td><code>↺</code></td><td>恢复图库的语言顺序。</td></tr><tr><td><strong>并排</strong></td><td>每种选中语言一列。窄窗口中各栏纵向堆叠。</td></tr><tr><td><strong>叠加</strong></td><td>所有选中语言画在同一个框内。</td></tr><tr><td><strong>正片叠底</strong>（仅叠加）</td><td>图层相乘，让线稿透出来。</td></tr><tr><td><strong>对齐对象</strong> 标签（仅叠加）</td><td>选择你正在拖动的语言，避免两栏同时移动。</td></tr></tbody></table><h2 id="遮蔽" tabindex="-1">遮蔽 <a class="header-anchor" href="#遮蔽" aria-label="Permalink to &quot;遮蔽&quot;">​</a></h2><p>遮蔽会盖住某种语言的画面，方便你检验自己的理解——相当于把答案盖住的自我测验。</p><table tabindex="0"><thead><tr><th>控件</th><th>行为</th></tr></thead><tbody><tr><td><strong>遮蔽：开 / 关</strong></td><td>总开关。<code>H</code> 切换；<code>Shift+H</code> 全部显示。</td></tr><tr><td>各语言的 <code>◐</code> / <code>◯</code> 标签</td><td>选择遮蔽哪些语言。</td></tr><tr><td><strong>遮蔽样式</strong></td><td><strong>模糊</strong> 或 <strong>色块</strong>。</td></tr><tr><td><strong>全遮</strong></td><td>重新遮蔽当前所有可见栏。</td></tr><tr><td><strong>全显</strong></td><td>关闭总开关。</td></tr><tr><td><strong>默认…</strong></td><td>记住哪些语言默认遮蔽，跨会话生效。</td></tr><tr><td>点击已遮蔽的栏</td><td>临时显示；再次点击画面可重新遮蔽。</td></tr></tbody></table><p>遮蔽只是<strong>阅读偏好</strong>。HTML 和 PNG 导出永远不会包含遮蔽。遮蔽默认值保存在浏览器中，不在页面 JSON 里。</p><figure class="shot"><img src="'+o+'" alt="对照阅读中中文和英文被模糊遮蔽，界面上有遮蔽样式选择与默认遮蔽勾选项"><figcaption>遮蔽中文和英文后的对照阅读。默认遮蔽会记住哪些语言一进来就遮住；点击被遮住的栏可以临时显示。</figcaption></figure><h2 id="缩放、平移与作用域" tabindex="-1">缩放、平移与作用域 <a class="header-anchor" href="#缩放、平移与作用域" aria-label="Permalink to &quot;缩放、平移与作用域&quot;">​</a></h2><ul><li>在某一栏上<strong>滚轮</strong>会缩放该语言。滚轮只在指针停在栏内时生效，所以页面其他地方的滚动照常。</li><li><strong>拖动</strong>某一栏可平移。</li><li><strong>拖动/缩放</strong>作用域有两种模式：<strong>整页</strong> 和 <strong>当前格</strong>。</li><li>按住 <code>Alt</code> 拖动或滚轮，只调整当前格，无论默认作用域是什么。</li><li><strong>上一格 / 下一格</strong> 在不离开当前视图的情况下切换焦点分格。</li><li><strong>全部复位</strong> 清除当前作用域内的偏移。</li></ul><p>每种语言有 <code>{ x, y, scale }</code>。<code>x</code> 和 <code>y</code> 是分格宽高的比例；<code>scale</code> 在 0.5× 到 3× 之间缩放裁切区域。</p><h2 id="对齐模式" tabindex="-1">对齐模式 <a class="header-anchor" href="#对齐模式" aria-label="Permalink to &quot;对齐模式&quot;">​</a></h2><p>对齐保存在页面 JSON 中，永远不会烘焙进图片。</p><table tabindex="0"><thead><tr><th>模式</th><th>行为</th><th>适用</th></tr></thead><tbody><tr><td><strong>整页偏移</strong></td><td>拖动任意分格都会平移该语言的整页。</td><td>整份扫描件存在相同偏移。</td></tr><tr><td><strong>逐格偏移</strong></td><td>每个分格有自己的偏移。</td><td>电子版与纸质版的分格位置不同。</td></tr><tr><td><strong>锚点对齐</strong></td><td>先在参考语言上点一个特征点，再在另一种语言上点同一点；偏移自动算出。</td><td>精确、可重复地对齐某个细节。</td></tr><tr><td><strong>网格吸附</strong></td><td>拖动时吸附到 0.5%、1%、2% 或 5% 的步长。</td><td>需要整齐、可复现的数值偏移。</td></tr></tbody></table><p>锚点模式会显示一条提示，说明参考语言。先在任意一格点一个特征点，再在另一格点同一位置。<strong>取消取点</strong> 清除待定锚点。待定的锚点不会保存。</p><h3 id="对齐设置" tabindex="-1">对齐设置 <a class="header-anchor" href="#对齐设置" aria-label="Permalink to &quot;对齐设置&quot;">​</a></h3><p><strong>对齐设置</strong> 会打开一个面板，包含：</p><ul><li><strong>目标</strong>语言标签。</li><li>所选目标的确切 <strong>X</strong>、<strong>Y</strong> 和 <strong>缩放</strong> 输入框。</li><li><strong>重置本页所有格</strong> —— 清除逐格偏移；整页偏移不受影响。</li><li><strong>重置当前格</strong> —— 只清除所选分格的逐格偏移。</li><li><strong>存为页预设</strong> / <strong>存为话预设</strong> —— 把当前对齐保存到 <code>data/presets/align.json</code>。</li><li>选择预设，然后 <strong>套用本页</strong> 或 <strong>套用整话</strong>；<strong>删除</strong> 移除预设。</li></ul><p>预设记录对齐模式、偏移、逐格偏移和网格步长。整话共享同一偏移时，套用话预设是修复整话的最快方式。</p><figure class="shot"><img src="'+a+'" alt="对齐设置面板：目标语言、X、Y、缩放输入、重置按钮与预设控件"><figcaption>对齐设置：选目标语言、直接输入精确数值，或把当前对齐存成页预设 / 话预设。</figcaption></figure><h2 id="对照阅读里的标注" tabindex="-1">对照阅读里的标注 <a class="header-anchor" href="#对照阅读里的标注" aria-label="Permalink to &quot;对照阅读里的标注&quot;">​</a></h2><p>标注工具栏在这里同样可用，而且比对生肉与熟肉的措辞差异，这里也是最快的地方。</p><ul><li>新标注沿用与工作台相同的作用范围：选中分格后，下一条标注会落在该格内。</li><li>对照视图默认显示标注层，方便边对照边标记；用<strong>标注</strong>开关可以隐藏。</li><li>标注在各视图之间共享：在对照阅读里画的标记，会出现在切格工作台和导出结果中。</li><li><code>Esc</code> 退出当前工具，<code>Delete</code> 删除选中的标注。</li></ul><h2 id="实用的对照流程" tabindex="-1">实用的对照流程 <a class="header-anchor" href="#实用的对照流程" aria-label="Permalink to &quot;实用的对照流程&quot;">​</a></h2><ol><li>在 <strong>对照阅读</strong>（<code>C</code>）中打开页面。</li><li>启用 <code>JA</code> + <code>ZH</code>（如有 <code>EN</code> 也启用），按你想要的阅读顺序排列。</li><li>如果各版本的分格差异不同，选 <strong>逐格偏移</strong>；否则先用 <strong>整页偏移</strong>。</li><li>拖动每种语言的栏，直到分格内容对齐。</li><li>如果本话其余页面共享同一偏移，保存一个对齐预设。</li><li>切到 <strong>叠加</strong> 并开启正片叠底，找出线稿或文字的差异。</li><li>打开遮蔽自测，然后逐栏显示。</li></ol><h2 id="行为细节" tabindex="-1">行为细节 <a class="header-anchor" href="#行为细节" aria-label="Permalink to &quot;行为细节&quot;">​</a></h2><ul><li>导出时也会应用对齐偏移，因此导出的裁切结果与你看到的画面一致。</li><li>阅读器需要先有分格。页面没有分格时，会提示前往切格工作台。</li><li>切换页面会保留遮蔽偏好，但清除临时显示。</li><li>每一栏带有笔记数；在这里选中分格后，新建笔记会限定到共享笔记栏中的该分格。</li><li>缺失的语言显示占位，而不是空白栏。</li></ul><figure class="shot"><img src="'+d+'" alt="对照工具栏：语言开关、遮蔽模式、并排与叠放、对齐范围，以及只拖动当前格的切换"><figcaption>对照工具栏：语言开关、遮蔽模式、并排 / 叠放、对齐范围，以及只拖动当前格的切换。</figcaption></figure><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>“这一页还没有分格。”</strong> 到 <strong>分格</strong>（<code>P</code>）运行 <strong>自动切格</strong>，然后返回。</li><li><strong>我拖动时其他语言也跟着动。</strong> 叠加模式下检查 <strong>对齐对象</strong> 标签；只有选中的语言会被拖动。</li><li><strong>缩放漂移了。</strong> 逐格缩放和逐格偏移与整页值分开存储。如果测试用的缩放没复位，重置当前格。</li><li><strong>滚动时画面乱跳。</strong> 滚轮只在指针停在栏内时生效；把指针移到页面边缘就能正常滚动。</li><li><strong>截图里出现了遮蔽。</strong> 遮蔽是界面偏好，不属于导出内容，但普通屏幕截图会带上它。</li><li><strong>某个标签是灰的。</strong> 该语言在本页没有图片。检查图库警告或卷的语言映射。</li></ul><h2 id="缺失的截图" tabindex="-1">缺失的截图 <a class="header-anchor" href="#缺失的截图" aria-label="Permalink to &quot;缺失的截图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>图</th><th>用于</th></tr></thead><tbody><tr><td>锚点模式步骤 1 / 步骤 2</td><td>参考点与算出的偏移</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/zh/guide/panels">切格工作台</a> —— 必须先有分格。</li><li><a href="/KomaYomi-docs/zh/guide/notes">笔记</a> —— 把观察记下来。</li><li><a href="/KomaYomi-docs/zh/guide/remote">远端存储与备份</a> —— 图片未缓存在本地时的行为。</li></ul>',38)])])}const q=e(l,[["render",g]]);export{_ as __pageData,q as default};
